$baselineRecords = Get-Content -LiteralPath 'C:/Users/robso/AppData/Local/Temp/skills-wave2-validation-Bu1zNV/performance-incident-response/baseline.json' -Raw | ConvertFrom-Json
foreach ($record in $baselineRecords) {
  $actual = (Get-FileHash -LiteralPath $record.Path).Hash
  if ($actual -ne $record.Hash) { throw "Hash mismatch: $($record.Path)" }
}
@{FilesVerified=$baselineRecords.Count;Unchanged=$true} | ConvertTo-Json | Tee-Object -FilePath 'C:/Users/robso/AppData/Local/Temp/skills-wave2-validation-Bu1zNV/performance-incident-response/unchanged-hashes.log'
